UPDATE provider_webhook_inbox i
LEFT JOIN store_platform_settings s
  ON s.platform_type = i.platform_type AND s.external_store_id = #{externalStoreId}
SET i.resolved_setting_id = s.id, i.resolved_setting_revision = s.connection_revision
WHERE i.id = #{inboxId} AND i.claim_version = #{claimVersion}
  AND i.status = 'PROCESSING' AND i.claimed_until >= CURRENT_TIMESTAMP(6)
